import {
  formatBp,
  groupDigits
} from "./chunk-TYQAEZ6P.js";

// src/threadKey.ts
function threadLabel(thread, own, picked = []) {
  const count = thread.count ?? 1;
  return count > 1 ? `${threadCount(thread)}${picked.length > 0 ? `, ${picked.join(", ")} among them` : ""}` : thread.pieces ? `${own}, one of its ${thread.pieces} pieces here` : own;
}
var threadCount = ({ count = 1 }) => `${groupDigits(count)} ${count === 1 ? "haplotype" : "haplotypes"}`;
var threadFoldKey = ({ belowBp }, reference) => `not drawn: sequence shorter than ${groupDigits(belowBp)} bp that a haplotype adds to ${reference} or skips of it before rejoining it`;
var threadFoldShortKey = ({ belowBp }) => `differences under ${formatBp(belowBp)} not drawn`;
var THREAD_LANE_KEY = "a lane is the haplotypes that take one drawn route";

export {
  threadLabel,
  threadCount,
  threadFoldKey,
  threadFoldShortKey,
  THREAD_LANE_KEY
};
