  TRACK_FITS,
  DEFAULT_TRACK_FIT,
  TRACK_FIT_LABELS,
  isTrackFit,
  scalesByWindow,
  drawnSegments,
  reachOver,
  referenceSegments,
  PAN_GLIDE,
  windowTranslateY,
  grownHeight,
