// src/keyColumn.ts
var LEGEND_INSET_PX = 6;
function keyColumnPx({ legendSize }) {
  return legendSize.width > 0 ? legendSize.width + 2 * LEGEND_INSET_PX : 0;
}
function fitBesideKey(m) {
  return {
    width: m.paneWidth - keyColumnPx(m),
    height: m.canvasHeight
  };
}
function keyColumnBox(m) {
  return {
    x0: m.paneWidth - keyColumnPx(m),
    x1: m.paneWidth,
    y0: 0,
    y1: m.canvasHeight
  };
}
function keyHeightPx(m) {
  return m.legendSize.height > 0 ? m.legendSize.height + 2 * LEGEND_INSET_PX + (m.referenceStripZonePx ?? 0) : 0;
}

export {
  LEGEND_INSET_PX,
  keyColumnPx,
  fitBesideKey,
  keyColumnBox,
  keyHeightPx
};
