import {
  curvePointAt
} from "./chunk-EIL6TOVA.js";

// src/util/strokeCover.ts
function flattenedPx(c, scaleX, scaleY, tolerance) {
  const px = {
    x0: c.x0 * scaleX,
    y0: c.y0 * scaleY,
    cx0: c.cx0 * scaleX,
    cy0: c.cy0 * scaleY,
    cx1: c.cx1 * scaleX,
    cy1: c.cy1 * scaleY,
    x1: c.x1 * scaleX,
    y1: c.y1 * scaleY
  };
  const bend = Math.max(
    Math.hypot(px.x0 - 2 * px.cx0 + px.cx1, px.y0 - 2 * px.cy0 + px.cy1),
    Math.hypot(px.cx0 - 2 * px.cx1 + px.x1, px.cy0 - 2 * px.cy1 + px.y1)
  );
  const n = Math.max(1, Math.ceil(Math.sqrt(0.75 * bend / tolerance)));
  return Array.from(
    { length: Number.isFinite(n) ? n + 1 : 0 },
    (_, k) => curvePointAt(px, k / n)
  );
}

export {
  flattenedPx
};
